#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# The deploy wizard: everything outside the NUC that the Deploy button (#71)
# needs, in Tailscale and in GitHub. Runs on the Mac, from a clone of the repo.
# Spec: #64, #74. Guide: docs/deployment/3-deploy-from-github.md.
#
# Every stage checks first and skips what is already done:
#   - The NUC's Tailscale state (route, key expiry, address) and its SSH host
#     key are read live over `ssh nuc`. That connection checks the NUC against
#     this Mac's known_hosts, so the host key read through it is the real one.
#   - GitHub is read with gh: the Environment, its branch rule, and when each
#     secret was last set. Secret values can't be read back.
#   - Tailscale's policy can't be read without an API key, so $ENV_FILE
#     records which NUC addresses the saved policy was written for.
# $ENV_FILE (gitignored) holds only public values: the policy record, the
# deploy public key, and the NUC address and host key last stored in GitHub.

ENVIRONMENT=production
TAILSCALE_ADMIN=https://login.tailscale.com/admin
PART2_URL=https://raw.githubusercontent.com/roelnoort/ChargeOnSolar/main/scripts/setup-nuc-2.sh
DEPLOY_KEYS=/home/deploy/.ssh/authorized_keys # the deploy user's keys, on the NUC
# Every secret .github/workflows/deploy.yml reads, under the same names.
DEPLOY_SECRETS=(TS_OAUTH_CLIENT_ID TS_OAUTH_SECRET DEPLOY_SSH_KEY NUC_SSH_HOST_KEY NUC_TAILSCALE_ADDRESS)

ok() { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }
already() { printf '  %s✓ already done:%s %s\n' "$GREEN" "$RESET" "$1"; }

# read_nuc: reads the NUC's Tailscale state and SSH host key over `ssh nuc`
# into the NUC_* variables. Fails when the NUC can't be reached.
NUC_STATE="" NUC_IP="" NUC_EXPIRY="" NUC_ADVERTISED="" NUC_APPROVED="" NUC_LAN="" NUC_HOSTKEY=""
read_nuc() {
  local out key value
  out=$(ssh -o BatchMode=yes -o ConnectTimeout=10 nuc bash -s 2>/dev/null <<'NUC'
status=$(tailscale status --json) || exit 1
prefs=$(tailscale debug prefs) || exit 1
lan=$(ip -4 route get 1.1.1.1 | awk '{ for (i = 1; i < NF; i++) if ($i == "src") print $(i + 1) }')
hostkey=$(cut -d' ' -f1,2 /etc/ssh/ssh_host_ed25519_key.pub) || exit 1
jq -rn --argjson s "$status" --argjson p "$prefs" --arg lan "$lan" --arg hostkey "$hostkey" '
  "state=\($s.BackendState // "")",
  "ip=\([$s.Self.TailscaleIPs[]? | select(startswith("100."))][0] // "")",
  "expiry=\($s.Self.KeyExpiry // "")",
  "advertised=\(($p.AdvertiseRoutes // []) | join(" "))",
  "approved=\(($s.Self.PrimaryRoutes // []) | join(" "))",
  "lan=\($lan)",
  "hostkey=\($hostkey)"'
NUC
  ) || return 1
  while IFS='=' read -r key value; do
    case "$key" in
      state) NUC_STATE=$value ;;
      ip) NUC_IP=$value ;;
      expiry) NUC_EXPIRY=$value ;;
      advertised) NUC_ADVERTISED=$value ;;
      approved) NUC_APPROVED=$value ;;
      lan) NUC_LAN=$value ;;
      hostkey) NUC_HOSTKEY=$value ;;
    esac
  done <<<"$out"
  [[ "$NUC_STATE" == Running && -n "$NUC_IP" ]]
}

# routes_approved: the NUC advertises a route, and Tailscale approved all of them.
routes_approved() {
  local route
  [[ -n "$NUC_ADVERTISED" ]] || return 1
  for route in $NUC_ADVERTISED; do
    [[ " $NUC_APPROVED " == *" $route "* ]] || return 1
  done
}

# recheck "what" TEST: after the User changed something in the dashboard,
# reads the NUC again until TEST passes or the User gives up.
recheck() {
  local what="$1" test="$2"
  while :; do
    pause "Done? Press Enter to check"
    read_nuc || warn "couldn't reach the NUC over ssh"
    if "$test"; then ok "$what"; return 0; fi
    warn "Tailscale doesn't show it yet."
    if ! confirm "Look again and check once more?"; then
      SKIPPED+=("$what: re-run scripts/setup-deploy.sh")
      return 1
    fi
  done
}

key_expiry_off() { [[ -z "$NUC_EXPIRY" ]]; }

# secret_updated NAME: when the Environment's secret NAME was last set; empty
# if it doesn't exist. The list is captured first, so a pipe can't cut gh short.
secret_updated() {
  local list
  list=$(gh secret list --env "$ENVIRONMENT" --repo "$REPO" --json name,updatedAt \
    -q '.[] | "\(.name) \(.updatedAt)"' 2>/dev/null || true)
  awk -v n="$1" '$1 == n { print $2 }' <<<"$list"
}
has_secret() { [[ -n "$(secret_updated "$1")" ]]; }

# put_secret NAME: stores stdin as the Environment's secret NAME, never on the
# command line, then proves it by its new timestamp. Feed it with a redirect,
# not a pipe: in a pipe it runs in a subshell, and its SKIPPED entry is lost.
put_secret() {
  local before after
  before=$(secret_updated "$1")
  if gh secret set "$1" --env "$ENVIRONMENT" --repo "$REPO" >/dev/null 2>&1; then
    after=$(secret_updated "$1")
    if [[ -n "$after" && "$after" != "$before" ]]; then
      WRITTEN_SECRET+=("$1")
      printf '  %s✓ saved%s %s in the Environment %s\n' "$GREEN" "$RESET" "$1" "$ENVIRONMENT"
      return 0
    fi
  fi
  warn "couldn't save $1 in the Environment $ENVIRONMENT"
  SKIPPED+=("the secret $1: re-run scripts/setup-deploy.sh")
  return 1
}

# put_public NAME VALUE: stores a public value as a secret (the workflow reads
# it from one), and records it in $ENV_FILE so a re-run can compare.
put_public() {
  if has_secret "$1" && [[ "$(_existing "$1" || true)" == "$2" ]]; then
    already "$1 is $2"
    return
  fi
  if put_secret "$1" < <(printf '%s' "$2"); then write_env "$1" "$2"; fi
}

# The Environment: exists, deployable from main only.
environment_json() { gh api "repos/$REPO/environments/$ENVIRONMENT" 2>/dev/null; }
branch_rules() {
  gh api "repos/$REPO/environments/$ENVIRONMENT/deployment-branch-policies" \
    -q '.branch_policies[] | "\(.id) \(.type // "branch") \(.name)"' 2>/dev/null
}
environment_ready() {
  local custom rules
  custom=$(environment_json | jq -r '.deployment_branch_policy.custom_branch_policies // false' 2>/dev/null) || return 1
  [[ "$custom" == true ]] || return 1
  rules=$(branch_rules) || return 1
  [[ "$(cut -d' ' -f2- <<<"$rules")" == "branch main" ]]
}

# tailscale_policy: the tailnet policy, for the NUC at NUC_IP. It replaces
# Tailscale's default "everything may reach everything", which would let a
# tag:ci device reach the whole home network too.
tailscale_policy() {
  local lan_deny=""
  [[ -n "$NUC_LAN" ]] && lan_deny=", \"$NUC_LAN:22\""
  cat <<POLICY
// ChargeOnSolar's deploy wizard (#74). Replaces the default policy, which let
// every device reach every other one.
{
	"tagOwners": {
		// GitHub's Deploy button joins your tailnet as a short-lived device with
		// this tag. Only admins (you) can give it out.
		"tag:ci": [],
	},
	"grants": [
		// Your own devices reach everything, as before: each other, and your
		// home network through the NUC. Tagged devices are not included.
		{"src": ["autogroup:member"], "dst": ["*"], "ip": ["*"]},
		// The Deploy button reaches only SSH on the NUC, and nothing else.
		{"src": ["tag:ci"], "dst": ["$NUC_IP"], "ip": ["tcp:22"]},
	],
	"ssh": [
		{
			"action": "check",
			"src":    ["autogroup:member"],
			"dst":    ["autogroup:self"],
			"users":  ["autogroup:nonroot", "root"],
		},
	],
	// Tailscale refuses to save this policy if one of these checks fails.
	"tests": [
		{
			"src":    "tag:ci",
			"accept": ["$NUC_IP:22"],
			"deny":   ["$NUC_IP:80", "$NUC_IP:443"$lan_deny],
		},
	],
}
POLICY
}

to_clipboard() { command -v pbcopy >/dev/null 2>&1 && printf '%s' "$1" | pbcopy; }

run_wizard() {

TOTAL_STAGES=9

# Run from the repo root, so gh targets this repository.
cd "$(dirname "$0")/.."
ENV_FILE="$PWD/.env.deploy"

for tool in gh jq ssh ssh-keygen curl; do
  command -v "$tool" >/dev/null 2>&1 || { echo "This wizard needs $tool." >&2; exit 1; }
done

# The deploy key pair is made in here and the folder is removed on exit, so
# the private key never stays on this Mac.
KEY_DIR=$(mktemp -d)
trap 'rm -rf "$KEY_DIR"' EXIT

banner "ChargeOnSolar: deploys from GitHub (Tailscale and the GitHub Environment)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Check GitHub and the NUC"
say "This wizard sets up Tailscale and GitHub so that the Deploy button can"
say "reach the NUC. It uses the GitHub CLI (gh) and 'ssh nuc' from chapter 1."
printf '\n'
if ! gh auth status >/dev/null 2>&1; then
  warn "gh is not logged in. Run: gh auth login, then run this wizard again."
  exit 1
fi
REPO=$(gh repo view --json nameWithOwner -q .nameWithOwner 2>/dev/null || true)
perm=$(gh repo view --json viewerPermission -q .viewerPermission 2>/dev/null || true)
if [[ -z "$REPO" ]]; then
  warn "gh can't tell which GitHub repository this is. Run the wizard from a clone of it."
  exit 1
fi
if [[ "$perm" != "ADMIN" ]]; then
  warn "You have ${perm:-no} access to $REPO; creating an Environment needs ADMIN."
  exit 1
fi
ok "gh is ready: $REPO (admin)"
if ! read_nuc; then
  warn "Couldn't read the NUC's Tailscale state over 'ssh nuc'."
  note "Check that 'ssh nuc' logs in without a password (chapter 1, step 7), and"
  note "that Tailscale on the NUC is up: ssh nuc tailscale status"
  exit 1
fi
ok "the NUC is on your tailnet at $NUC_IP"
pause "Press Enter to continue"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Tailscale: approve the NUC's home network route"
if routes_approved; then
  already "Tailscale passes $NUC_ADVERTISED on through the NUC"
else
  say "The NUC offers your home network ($NUC_ADVERTISED) to your other Tailscale"
  say "devices, so charge.<domain> works from away. Tailscale needs your approval."
  printf '\n'
  open_url "$TAILSCALE_ADMIN/machines"
  step "Log in with your Tailscale account if asked. You are on Machines."
  step "Click the device 'nuc' (it has a Subnets badge)."
  step "In its Subnets section, tick $NUC_ADVERTISED and click Save."
  recheck "the NUC's route $NUC_ADVERTISED is approved" routes_approved || true
fi
pause "Press Enter to continue"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Tailscale: turn off key expiry for the NUC"
if key_expiry_off; then
  already "the NUC's key never expires"
else
  say "Tailscale logs devices out after 180 days unless you log in again. The NUC"
  say "has no one to do that, so switch it off for the NUC only."
  printf '\n'
  open_url "$TAILSCALE_ADMIN/machines"
  step "In the row of 'nuc', click the ⋯ menu at the far right."
  step "Choose Disable Key Expiry."
  recheck "the NUC's key expiry is off" key_expiry_off || true
fi
pause "Press Enter to continue"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "GitHub: the Environment $ENVIRONMENT"
say "The deploy secrets live in the GitHub Environment '$ENVIRONMENT', which only"
say "runs from main: a workflow on any other branch never gets them."
printf '\n'
if environment_ready; then
  already "the Environment $ENVIRONMENT exists and only main may deploy to it"
else
  if ! gh api -X PUT "repos/$REPO/environments/$ENVIRONMENT" --input - >/dev/null 2>&1 <<'JSON'
{ "deployment_branch_policy": { "protected_branches": false, "custom_branch_policies": true } }
JSON
  then
    warn "GitHub refused to create or update the Environment $ENVIRONMENT."
    exit 1
  fi
  rules=$(branch_rules || true)
  if ! grep -q ' branch main$' <<<"$rules"; then
    gh api -X POST "repos/$REPO/environments/$ENVIRONMENT/deployment-branch-policies" \
      -f name=main -f type=branch >/dev/null 2>&1 || warn "couldn't add the rule 'main'"
  fi
  # The rules come in on fd 3, so confirm still reads the keyboard.
  while read -r id type name <&3; do
    [[ -n "$id" && "$type $name" != "branch main" ]] || continue
    warn "The Environment also allows the $type '$name'."
    if confirm "Remove that rule, so only main may deploy?"; then
      gh api -X DELETE "repos/$REPO/environments/$ENVIRONMENT/deployment-branch-policies/$id" >/dev/null 2>&1 ||
        warn "couldn't remove it"
    fi
  done 3<<<"$(branch_rules || true)"
  if environment_ready; then
    ok "the Environment $ENVIRONMENT exists and only main may deploy to it"
  else
    warn "The Environment isn't limited to main yet."
    SKIPPED+=("limit the Environment to main: https://github.com/$REPO/settings/environments")
  fi
fi
# A repository secret with the same name would fill in for a missing one.
repo_secrets=$(gh secret list --repo "$REPO" --json name -q '.[].name' 2>/dev/null || true)
for name in "${DEPLOY_SECRETS[@]}"; do
  if grep -qxF "$name" <<<"$repo_secrets"; then
    warn "The repository itself has a secret $name: delete it (gh secret delete $name),"
    note "  otherwise every workflow can read it, and it fills in when $ENVIRONMENT lacks one."
    SKIPPED+=("delete the repository secret $name: gh secret delete $name")
  fi
done
pause "Press Enter to continue"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Tailscale: the tag tag:ci and the access policy"
policy_for="$NUC_IP $NUC_LAN"
if [[ "$(_existing TAILSCALE_POLICY_FOR || true)" == "$policy_for" ]] &&
  ! confirm "The policy for the NUC at $NUC_IP is already saved. Show it again?"; then
  already "the policy limiting tag:ci to SSH on the NUC"
else
  say "Tailscale's default policy lets every device reach every other one. This"
  say "one creates the tag tag:ci for the Deploy button and lets it reach only SSH"
  say "on the NUC ($NUC_IP). Your own devices keep reaching everything."
  printf '\n'
  policy=$(tailscale_policy)
  printf '%s%s%s\n\n' "$DIM" "$policy" "$RESET"
  if to_clipboard "$policy"; then
    ok "copied the policy to the clipboard"
  else
    note "Copy the policy above, from the first // line to the last }."
  fi
  open_url "$TAILSCALE_ADMIN/acls/file"
  step "You are on Access controls, in the policy file editor."
  step "Click in the editor, select everything (Cmd-A) and paste (Cmd-V)."
  step "Click Save."
  note "Tailscale checks the 'tests' at the bottom while saving: it refuses the policy"
  note "if tag:ci could reach anything but SSH on the NUC."
  if confirm "Did Tailscale save it?"; then
    write_env TAILSCALE_POLICY_FOR "$policy_for"
  else
    warn "Read the error Tailscale shows, and re-run this wizard."
    SKIPPED+=("the Tailscale access policy: re-run scripts/setup-deploy.sh")
  fi
fi
pause "Press Enter to continue"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Tailscale: an OAuth client for the Deploy button"
make_client=true
if has_secret TS_OAUTH_CLIENT_ID && has_secret TS_OAUTH_SECRET; then
  already "TS_OAUTH_CLIENT_ID and TS_OAUTH_SECRET are in $ENVIRONMENT"
  confirm "Make a new OAuth client and replace them?" || make_client=false
fi
if $make_client; then
  say "The Deploy button joins your tailnet with an OAuth client that may only"
  say "add short-lived devices tagged tag:ci."
  printf '\n'
  open_url "$TAILSCALE_ADMIN/settings/trust-credentials"
  step "You are on Settings → Trust credentials. Click the Credential button."
  step "Choose OAuth. Description: GitHub Deploy (ChargeOnSolar)."
  step "In the list of operations, find Auth Keys (under Keys) and choose Write."
  step "Add the tag tag:ci. Leave every other operation off."
  step "Click Generate credential."
  warn "The secret is shown only once: leave that page open until it's saved."
  printf '\n'
  TS_OAUTH_CLIENT_ID="" TS_OAUTH_SECRET=""
  while :; do
    if ! ask TS_OAUTH_CLIENT_ID "Client ID:" ||
      ! ask_secret TS_OAUTH_SECRET "Client secret (hidden, starts with tskey-client-):"; then
      SKIPPED+=("the Tailscale OAuth client: re-run scripts/setup-deploy.sh")
      break
    fi
    if [[ -n "$TS_OAUTH_CLIENT_ID" && "$TS_OAUTH_SECRET" == tskey-client-* ]]; then
      # The secret goes through a file descriptor, so it never shows in `ps`.
      code=$(curl -s -o /dev/null -w '%{http_code}' --max-time 15 \
        --data-urlencode "client_id=$TS_OAUTH_CLIENT_ID" \
        --data-urlencode client_secret@<(printf '%s' "$TS_OAUTH_SECRET") \
        https://api.tailscale.com/api/v2/oauth/token || true)
      if [[ "$code" == 200 ]]; then
        ok "Tailscale accepts the client"
        put_secret TS_OAUTH_CLIENT_ID < <(printf '%s' "$TS_OAUTH_CLIENT_ID") || true
        put_secret TS_OAUTH_SECRET < <(printf '%s' "$TS_OAUTH_SECRET") || true
        note "You can close the Credential created page now (click Done)."
        note "Replaced an older client? Delete that one on the same page."
        break
      fi
      if [[ "$code" == 000 || -z "$code" ]]; then
        warn "Couldn't reach Tailscale to check them. Check the internet connection."
      else
        warn "Tailscale rejected the client ID and secret (HTTP $code)."
      fi
    else
      warn "That doesn't look right: the secret starts with tskey-client-."
    fi
    confirm "Copy them again?" || { SKIPPED+=("the Tailscale OAuth client: re-run scripts/setup-deploy.sh"); break; }
  done
  TS_OAUTH_SECRET=""
fi
pause "Press Enter to continue"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "GitHub: the deploy key"
say "The Deploy button logs in to the NUC with its own SSH key. The private key"
say "goes only into $ENVIRONMENT; this Mac keeps just the public key."
printf '\n'
make_key=true
# A replaced key needs the old one removed on the NUC: part 2 skips stage 5
# while the deploy user has any restricted key.
key_replaced=false had_key=false
if has_secret DEPLOY_SSH_KEY; then
  had_key=true
  if [[ -n "$(_existing DEPLOY_PUBLIC_KEY || true)" ]]; then
    already "DEPLOY_SSH_KEY is in $ENVIRONMENT"
    confirm "Make a new key pair and replace it?" || make_key=false
  else
    warn "DEPLOY_SSH_KEY is set, but this Mac no longer knows its public key."
    confirm "Make a new key pair (you then paste the new public key on the NUC)?" || make_key=false
    $make_key || SKIPPED+=("the deploy public key: re-run and make a new key pair")
  fi
fi
if $make_key; then
  rm -f "$KEY_DIR/deploy" "$KEY_DIR/deploy.pub"
  ssh-keygen -q -t ed25519 -N "" -C "chargeonsolar-deploy" -f "$KEY_DIR/deploy"
  if put_secret DEPLOY_SSH_KEY <"$KEY_DIR/deploy"; then
    write_env DEPLOY_PUBLIC_KEY "$(cat "$KEY_DIR/deploy.pub")"
    key_replaced=$had_key
  fi
  rm -f "$KEY_DIR/deploy" "$KEY_DIR/deploy.pub"
  note "The private key is deleted from this Mac. Lose it? Re-run and make a new one."
fi
pause "Press Enter to continue"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "GitHub: the NUC's address and SSH host key"
say "The Deploy button connects to the NUC's Tailscale address, and refuses to"
say "talk to any machine there whose SSH host key isn't the NUC's."
printf '\n'
put_public NUC_TAILSCALE_ADDRESS "$NUC_IP"
if [[ "$NUC_HOSTKEY" == ssh-ed25519\ * ]]; then
  put_public NUC_SSH_HOST_KEY "$NUC_HOSTKEY"
  note "  fingerprint $(ssh-keygen -l -f - <<<"$NUC_HOSTKEY" | cut -d' ' -f2)"
else
  warn "Couldn't read the NUC's host key (/etc/ssh/ssh_host_ed25519_key.pub)."
  SKIPPED+=("the secret NUC_SSH_HOST_KEY: re-run scripts/setup-deploy.sh")
fi
missing=()
for name in "${DEPLOY_SECRETS[@]}"; do has_secret "$name" || missing+=("$name"); done
if ((${#missing[@]})); then
  warn "$ENVIRONMENT still lacks: ${missing[*]}"
else
  ok "$ENVIRONMENT holds all ${#DEPLOY_SECRETS[@]} secrets the Deploy button needs"
fi
pause "Press Enter to continue"

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "The NUC: let the deploy key in"
public_key=$(_existing DEPLOY_PUBLIC_KEY || true)
if [[ -z "$public_key" ]]; then
  warn "There is no deploy public key yet: re-run this wizard to make one."
else
  say "The NUC lets the deploy key in once part 2 of the NUC wizard has it. Run"
  say "part 2 again and paste this key at stage 5, 'Deploys from GitHub'. Every other"
  say "stage reports that it's already done."
  printf '\n  %s\n\n' "$public_key"
  to_clipboard "$public_key" && ok "copied the public key to the clipboard"
  remove_old=""
  if $key_replaced; then
    warn "This key replaces the old one, so remove the old one from the NUC first:"
    note "part 2 skips stage 5 while the NUC still has a deploy key."
    remove_old="sudo rm -f $DEPLOY_KEYS && "
  elif ! $make_key; then
    note "Already pasted it on an earlier run? Then you can skip this."
  fi
  if confirm "Run part 2 on the NUC now, from here (it asks for your NUC password)?"; then
    # shellcheck disable=SC2029 # These are meant to expand here, on the Mac.
    ssh -t nuc "${remove_old}curl -fsSLO $PART2_URL && sudo bash setup-nuc-2.sh" ||
      SKIPPED+=("paste the deploy public key: ssh nuc, then sudo bash setup-nuc-2.sh")
  else
    step "In another terminal: ssh nuc"
    $key_replaced && step "Then: sudo rm $DEPLOY_KEYS"
    step "Then: curl -fsSLO $PART2_URL"
    step "And:  sudo bash setup-nuc-2.sh   (paste the key at stage 5)"
  fi
fi
pause "Press Enter to finish"

finish
note "Public values this wizard stored are recorded in $ENV_FILE."
say "Next: in GitHub, Actions → Deploy → Run workflow (chapter 3, step 3)."
printf '\n'
}

run_wizard "$@"; exit
